<div class="flex min-h-12 flex-wrap items-center justify-center" x-data="{ expanded:false }">
    <template x-for="person in {{ $expression }}.slice(0, expanded ? undefined : 5)" :key="person.id"><button type="button" @click.stop="selectedStaff=person" class="group relative -ml-2 first:ml-0 transition duration-300 hover:z-20 hover:-translate-y-1 hover:scale-110"><span class="journey-avatar-glow absolute inset-0 rounded-full"></span><img :src="person.avatar" :alt="person.name" x-on:error="$event.target.onerror=null; $event.target.src=person.avatar_fallback" class="relative h-10 w-10 rounded-full border-[3px] border-slate-700 object-cover shadow-lg {{ ($muted ?? false) ? 'grayscale opacity-60' : '' }}" :class="person.completed_daily>=person.total_daily?'ring-2 ring-amber-400 border-amber-200':''"><span x-show="person.completed_daily>=person.total_daily" class="absolute -bottom-1 -right-1 z-10 grid h-5 w-5 place-items-center rounded-full bg-amber-400 text-[10px] shadow">🏆</span><span class="pointer-events-none absolute bottom-[calc(100%+10px)] left-1/2 z-50 hidden w-48 -translate-x-1/2 rounded-xl border border-white/10 bg-slate-950 p-3 text-left text-xs text-white shadow-2xl group-hover:block"><strong class="block text-sm" x-text="person.name"></strong><span class="block text-slate-300" x-text="person.unit"></span><span class="mt-2 block" x-text="`${person.completed_daily} / ${person.total_daily} aktivitas`"></span><span class="block" x-text="percentage(person).toFixed(1)+'% tuntas'"></span><b class="mt-1 block text-cyan-300" x-text="status(person)"></b><span x-show="person.completed_daily > 0" class="mt-1 block font-bold text-emerald-300" x-text="checkpointFinishLabel(person, person.completed_daily)"></span></span></button></template>
    <button type="button" x-show="!expanded && {{ $expression }}.length>5" @click.stop="expanded=true" class="relative -ml-2 grid h-10 w-10 place-items-center rounded-full border-2 border-slate-600 bg-slate-800 text-xs font-bold text-white shadow" x-text="'+'+({{ $expression }}.length-5)"></button>
    <span x-show="{{ $expression }}.length===0" class="grid h-10 w-10 place-items-center rounded-full border border-dashed border-slate-600 text-slate-600">–</span>
</div>
